const lessons = [
  {id:'basics',no:'01',title:'先认识“量”',subtitle:'从一句话里找出能变的数字',tag:'数学语言',intro:'数量关系不是先找公式，而是先问：题目里有哪几个量？谁随着谁变化？',insight:'把“一共”想成许多相同小份加起来。3 支笔每支 4 元，就是 3 个 4 元。',formula:'总价 = 单价 × 数量',steps:[['找对象','有多少支笔？每支多少钱？'],['找关系','每多一支，总价增加一个单价。'],['写算式','相同的几份，用乘法连起来。']],example:'一支笔 4 元，买 5 支需要多少钱？',solution:['单价是 4 元，数量是 5 支。','总价 = 4 × 5 = 20 元。','反过来检查：20 ÷ 5 = 4 元/支。'],pitfall:'“每”往往提示单位量；“一共”往往提示求总量。',quiz:{prompt:'一盒彩笔 6 元，买 4 盒，一共需要多少元？',options:['10 元','20 元','24 元','30 元'],answer:2,hint:'把 4 个 6 元加起来，也可以用乘法。',explain:'6 × 4 = 24 元。先辨认单价与数量，再求总价。'},explorer:'basics'},
  {id:'equation',no:'02',title:'把文字翻译成等式',subtitle:'用一个未知数搭出“天平”',tag:'数学语言',intro:'有些题先不必求答案。把已知条件准确放到等号两边，难题就变成了可计算的等式。',insight:'“比原来多 7 个”是原来的数量 + 7；“一共 19 个”是等号另一边的总量。',formula:'原来的量 + 增加的量 = 现在的量',steps:[['设未知','不知道的量，暂时叫 x。'],['翻译词语','“多 7”写成 x + 7。'],['保持平衡','等号两边同时减 7，得到 x。']],example:'盒里原来有一些球，又放入 7 个，现在有 19 个。原来有几个？',solution:['设原来有 x 个。','x + 7 = 19。','等号两边同时减 7，x = 12。'],pitfall:'“比 A 多 7”指 A + 7；一定先确定谁是参照量。',quiz:{prompt:'一桶水用掉 8 升后还剩 15 升，原来有多少升？',options:['7 升','15 升','23 升','120 升'],answer:2,hint:'原来 − 用掉 = 剩下。',explain:'设原来有 x 升，x − 8 = 15，所以 x = 23。'},explorer:'equation'},
  {id:'work',no:'03',title:'工程问题',subtitle:'把“一项任务”切成均匀小块',tag:'高频题型',intro:'工程问题关注三件事：总共要做多少、每天能做多少、需要多少天。合作时，每天完成量可以相加。',insight:'甲 6 天做完、乙 8 天做完，可先把总量想成 24 份：甲每天 4 份，乙每天 3 份。',formula:'工作总量 = 工作效率 × 工作时间',steps:[['赋总量','把总任务设为两个时间的公倍数。'],['求效率','每人的效率 = 总量 ÷ 单独时间。'],['算合作','合作时间 = 总量 ÷ 效率之和。']],example:'甲独做 6 天，乙独做 8 天。两人合作几天完成？',solution:['设总量为 24 份。','甲每天 4 份，乙每天 3 份。','合作每天 7 份，需 24 ÷ 7 ≈ 3.43 天。'],pitfall:'合作效率是“每天完成量”相加，不是两个天数相加。',quiz:{prompt:'甲独做 6 天，乙独做 3 天。合作完成需要几天？',options:['1 天','2 天','3 天','9 天'],answer:1,hint:'把总量设成 6 份，甲每天 1 份，乙每天 2 份。',explain:'每天合做 3 份，6 ÷ 3 = 2 天。'},explorer:'work'},
  {id:'motion',no:'04',title:'行程问题',subtitle:'让路程、速度、时间动起来',tag:'高频题型',intro:'速度表示单位时间走过的路程。两人相向而行时，两人的速度都在缩短中间的距离。',insight:'相向而行看速度和，追赶同向看速度差。先画出方向，公式就不容易用反。',formula:'路程 = 速度 × 时间',steps:[['画方向','先看相向、同向还是往返。'],['统一单位','公里、小时要配套使用。'],['找速度关系','相遇用速度和，追及用速度差。']],example:'两地相距 150 公里，甲乙相向而行，速度分别为 60、40 公里/时，多久相遇？',solution:['一小时内，两人合计靠近 60 + 40 = 100 公里。','需要缩短 150 公里。','时间 = 150 ÷ 100 = 1.5 小时。'],pitfall:'相向而行要相加；同向追及才常用相减。',quiz:{prompt:'两车相距 180 公里，相向开来，速度分别为 60 和 30 公里/时。几小时相遇？',options:['1 小时','2 小时','3 小时','6 小时'],answer:1,hint:'每小时一起缩短 60 + 30 = 90 公里。',explain:'180 ÷ (60 + 30) = 2 小时。'},explorer:'motion'},
  {id:'profit',no:'05',title:'利润与折扣',subtitle:'从成本 100 元开始想',tag:'高频题型',intro:'题目出现百分比时，先找百分比是“以谁为基准”。利润率通常以成本为分母。',insight:'成本设成 100 元后，20% 利润就是 20 元；八折意味着售价乘 0.8。',formula:'利润率 = (售价 − 成本) ÷ 成本',steps:[['找基准','成本、标价、实售价分别是多少？'],['按顺序变','先打折，再减成本。'],['算利润率','利润除以成本，不是除以售价。']],example:'成本 100 元，标价 150 元，打八折卖出。利润率是多少？',solution:['实售价 = 150 × 0.8 = 120 元。','利润 = 120 − 100 = 20 元。','利润率 = 20 ÷ 100 = 20%。'],pitfall:'八折是乘 80%；降价 8% 是乘 92%，两者不一样。',quiz:{prompt:'一件商品成本 80 元，售价 100 元，利润率是多少？',options:['20%','25%','80%','125%'],answer:1,hint:'利润 20 元，要除以成本 80 元。',explain:'(100 − 80) ÷ 80 = 25%。'},explorer:'profit'},
  {id:'sets',no:'06',title:'容斥原理',subtitle:'让重复的人只数一次',tag:'高频题型',intro:'两群人有重叠时，直接把人数相加会把中间那群人算两次。用圆圈把重叠区画出来。',insight:'会 A 的人数 + 会 B 的人数，重复算了“都会”的人数一次，所以要减回来。',formula:'至少会一种 = A + B − 两种都会',steps:[['画两个圈','一个圈代表 A，一个圈代表 B。'],['填重叠区','把“两者都满足”的人放中间。'],['只数一次','相加后减去一次重叠。']],example:'全班 40 人，会英语 25 人，会法语 20 人，两种都会 10 人。两种都不会的有几人？',solution:['至少会一种 = 25 + 20 − 10 = 35 人。','全班 40 人。','都不会 = 40 − 35 = 5 人。'],pitfall:'“只会 A”和“会 A”不同；后者包含两种都会的人。',quiz:{prompt:'50 人中，30 人会英语，25 人会法语，10 人两种都会。两种都不会的有几人？',options:['0 人','5 人','10 人','15 人'],answer:1,hint:'先求至少会一门：30 + 25 − 10。',explain:'至少会一门 45 人，都不会 = 50 − 45 = 5 人。'},explorer:'sets'},
  {id:'mixture',no:'07',title:'浓度问题',subtitle:'水变多，溶质不会凭空增加',tag:'高频题型',intro:'浓度是“溶质占整杯溶液的比例”。只加水时，溶质不变，总量增加，所以浓度下降。',insight:'不必背十字交叉法，先守住不变量：加水不改变溶质的质量。',formula:'浓度 = 溶质质量 ÷ 溶液总质量',steps:[['求溶质','原溶液 × 原浓度。'],['更新总量','加入水后，溶液总量增加。'],['重新相除','新浓度 = 原溶质 ÷ 新总量。']],example:'100 克、20% 的盐水，再加入 100 克清水，新浓度是多少？',solution:['原溶质 = 100 × 20% = 20 克。','新溶液总量 = 100 + 100 = 200 克。','新浓度 = 20 ÷ 200 = 10%。'],pitfall:'加水时变的是总质量，不是盐的质量。',quiz:{prompt:'200 克、10% 的盐水，加入 200 克清水后，浓度是多少？',options:['2.5%','5%','10%','20%'],answer:1,hint:'盐仍是 20 克，现在一共 400 克。',explain:'20 ÷ 400 = 5%。'},explorer:'mixture'},
  {id:'counting',no:'08',title:'排列与组合',subtitle:'先问顺序重不重要',tag:'进阶入门',intro:'“从 5 人中选 2 名代表”与“选队长和副队长”不同。前者不分顺序，后者分角色，因此结果数量不同。',insight:'两人互换后仍是同一种选择，就是组合；互换后变成另一种结果，就是排列。',formula:'有顺序用排列 · 无顺序用组合',steps:[['先问顺序','A、B 互换是否算新结果？'],['分步选择','有顺序时，先选第一位再选第二位。'],['去掉重复','无顺序时，同一组的不同顺序只算一次。']],example:'5 人中选 2 名代表，有多少种选法？',solution:['先按顺序选：第一人有 5 种，第二人有 4 种，共 20 种。','每组两人被算了 2 次，例如甲乙和乙甲。','20 ÷ 2 = 10 种。'],pitfall:'“选人”和“安排职位”常常不是同一道题。',quiz:{prompt:'5 人中选 1 名队长、1 名副队长，共有多少种安排？',options:['10 种','15 种','20 种','25 种'],answer:2,hint:'队长和副队长交换后，是新的安排。',explain:'队长有 5 种选法，副队长剩 4 种，共 5 × 4 = 20 种。'},explorer:'counting'}
];

const STORAGE_KEY='jieti-youxing-progress-v1';
const opposite={A:'F',F:'A',B:'D',D:'B',C:'E',E:'C'};
const faceNames={A:'圆',B:'三角',C:'星',D:'方',E:'十字',F:'点'};
const spatialQuestions=[{from:'A',options:['B','C','D','F'],answer:'F'},{from:'B',options:['A','C','D','E'],answer:'D'},{from:'C',options:['A','B','E','F'],answer:'E'}];
const signalTips={position:'元素完全相同时，盯住同一个元素的位置和朝向；比较每次移动的方向与步数。',style:'图形相似且有重合线条时，试试叠加、保留共同部分，或只留下不同部分。',mark:'小黑点、圆圈或三角可能是关键标记；先看它落在哪条线、哪个角或哪个区域。',attribute:'图形很规则时，先看是否轴对称、中心对称，再看曲直与封闭。',count:'外形差别大时，数点、线、角、封闭面和独立部分；找数列变化。',space:'出现展开图时，先定位相对面，再排除把相对面画成相邻面的选项。'};
let state=loadState();let currentLesson=state.lastLesson||'basics';let currentView='home';let hintShown=false;let answered=false;let spatialIndex=0;let spatialAnswered=false;let cubeX=-25,cubeY=-32;let drag=null;
function loadState(){try{let raw=JSON.parse(localStorage.getItem(STORAGE_KEY));return {mastered:raw?.mastered||[],attempts:raw?.attempts||[],reviews:raw?.reviews||[],lastLesson:raw?.lastLesson||'basics'}}catch{return {mastered:[],attempts:[],reviews:[],lastLesson:'basics'}}}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}catch{}refreshStats()}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function switchView(view,focus=true){if(!['home','quantity','spatial','review'].includes(view))view='home';currentView=view;document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active-view',x.id===view+'-view'));document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===view));document.getElementById('crumb-current').textContent={home:'学习首页',quantity:'数量关系',spatial:'空间图推',review:'错题复盘'}[view];document.querySelector('.sidebar').classList.remove('open');document.getElementById('mobile-menu').setAttribute('aria-expanded','false');if(view==='review')renderReviews();if(view==='quantity')renderLesson();window.scrollTo({top:0,behavior:'smooth'});if(focus)document.getElementById('main-content').focus({preventScroll:true});history.replaceState(null,'','#'+view)}
document.querySelectorAll('[data-view]').forEach(el=>el.addEventListener('click',()=>switchView(el.dataset.view)));
document.querySelectorAll('[data-go]').forEach(el=>el.addEventListener('click',()=>switchView(el.dataset.go)));
document.getElementById('mobile-menu').addEventListener('click',()=>{const side=document.querySelector('.sidebar');side.classList.toggle('open');document.getElementById('mobile-menu').setAttribute('aria-expanded',side.classList.contains('open'))});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('.sidebar').classList.remove('open')});

function refreshStats(){let count=state.mastered.length;let open=state.reviews.filter(x=>!x.reviewed).length;document.getElementById('nav-lesson-count').textContent=count+'/8';document.getElementById('nav-error-count').textContent=open;document.getElementById('home-complete').textContent=count;document.getElementById('home-attempts').textContent=state.attempts.length;document.getElementById('home-reviews').textContent=open;document.getElementById('home-progress-bar').style.width=(count/8*100)+'%';document.getElementById('home-progress-text').textContent=count?`已完成 ${count} 个知识点，继续保持节奏。`:'从第一课开始，建立你的基础。';document.getElementById('quantity-progress').textContent=count+' / 8';document.getElementById('review-total').textContent=state.attempts.length;document.getElementById('review-open').textContent=open;document.getElementById('review-week').textContent=state.attempts.filter(x=>x.correct&&Date.now()-new Date(x.date).getTime()<7*86400000).length}

function renderLessonNav(){document.getElementById('lesson-nav').innerHTML=lessons.map(l=>`<button class="lesson-nav-item ${l.id===currentLesson?'selected':''}" data-lesson="${l.id}"><span class="num">${l.no}</span><span><b>${l.title}</b><small>${l.subtitle}</small></span>${state.mastered.includes(l.id)?'<span class="done">✓</span>':''}</button>`).join('');document.querySelectorAll('[data-lesson]').forEach(b=>b.addEventListener('click',()=>{currentLesson=b.dataset.lesson;state.lastLesson=currentLesson;save();renderLesson();document.getElementById('quantity-title').scrollIntoView({behavior:'smooth'})}))}
function renderLesson(){let l=lessons.find(x=>x.id===currentLesson)||lessons[0];hintShown=false;answered=false;renderLessonNav();document.getElementById('lesson-content').innerHTML=`<div class="lesson-meta">LESSON ${l.no} / 08 · ${l.tag}</div><div class="lesson-title-row"><h2>${l.title}</h2>${state.mastered.includes(l.id)?'<span class="mastery-pill">✓ 已掌握</span>':''}</div><p class="lesson-desc">${l.subtitle}</p><div class="lesson-block"><div class="block-label">01 / UNDERSTAND</div><h3>先把问题说清楚</h3><p>${l.intro}</p><div class="insight-box">✳　${l.insight}</div><div class="formula-box"><span>∑</span><strong>${l.formula}</strong></div></div><div class="lesson-block"><div class="block-label">02 / BREAK IT DOWN</div><h3>解题只走这三步</h3><div class="steps">${l.steps.map((s,i)=>`<div class="step"><span>0${i+1}</span><b>${s[0]}</b><small>${s[1]}</small></div>`).join('')}</div></div><div class="lesson-block"><div class="block-label">03 / PLAY WITH THE NUMBERS</div><h3>动手调一调</h3><p>拖动数字，观察图形和结果怎样一起变化。先形成直觉，再记方法。</p><div class="explorer" id="explorer"></div></div><div class="lesson-block"><div class="block-label">04 / WORKED EXAMPLE</div><h3>跟着做一道</h3><div class="worked-card"><div class="question">${l.example}</div><ol>${l.solution.map(s=>`<li>${s}</li>`).join('')}</ol></div><div class="mistake-note"><span>↗</span><span><b>容易混淆：</b>${l.pitfall}</span></div></div><div class="lesson-block"><div class="block-label">05 / YOUR TURN</div><h3>现在试一试</h3><div class="quiz-card"><h4>原创模拟练习</h4><p class="quiz-prompt">${l.quiz.prompt}</p><div class="quiz-options">${l.quiz.options.map((o,i)=>`<button class="option-btn" data-answer="${i}"><span class="letter">${'ABCD'[i]}</span><span>${o}</span></button>`).join('')}</div><div id="lesson-feedback" class="quiz-feedback" aria-live="polite"></div><div class="quiz-actions"><button class="subtle-btn" id="show-hint">给我一点提示 →</button><button class="subtle-btn" id="retry-quiz" hidden>再试一次 ↺</button></div></div></div><div class="lesson-footer"><small>每题都是原创模拟题，用来练习方法，不标作真题。</small><button class="primary-btn" id="next-lesson">${l.no==='08'?'去看错题复盘':'下一知识点'} <span>→</span></button></div>`;
  renderExplorer(l.explorer);document.querySelectorAll('#lesson-content [data-answer]').forEach(b=>b.addEventListener('click',()=>answerLesson(l,+b.dataset.answer)));document.getElementById('show-hint').addEventListener('click',()=>{if(answered)return;hintShown=true;document.getElementById('lesson-feedback').className='quiz-feedback';document.getElementById('lesson-feedback').textContent='提示：'+l.quiz.hint});document.getElementById('retry-quiz').addEventListener('click',()=>renderLesson());document.getElementById('next-lesson').addEventListener('click',()=>{let idx=lessons.findIndex(x=>x.id===currentLesson);if(idx===lessons.length-1){switchView('review')}else{currentLesson=lessons[idx+1].id;state.lastLesson=currentLesson;save();renderLesson();document.getElementById('quantity-title').scrollIntoView({behavior:'smooth'})}})
}
function answerLesson(l,index){if(answered)return;answered=true;let correct=index===l.quiz.answer;state.attempts.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),kind:'quantity',topic:l.id,correct,date:new Date().toISOString()});if(correct&&!state.mastered.includes(l.id))state.mastered.push(l.id);if(!correct)addReview({kind:'quantity',topic:l.id,title:l.title,question:l.quiz.prompt,chosen:l.quiz.options[index],answer:l.quiz.options[l.quiz.answer],explain:l.quiz.explain});save();document.querySelectorAll('#lesson-content [data-answer]').forEach((b,i)=>{b.disabled=true;if(i===l.quiz.answer)b.classList.add('correct');if(i===index&&!correct)b.classList.add('wrong')});let f=document.getElementById('lesson-feedback');f.className='quiz-feedback '+(correct?'good':'bad');f.innerHTML=(correct?'✓ 答对了！':'这一步再想想。')+' '+esc(l.quiz.explain)+(correct?'<br>这一课已计入“已掌握”。':'<br>已加入错题复盘，可记录卡点后再试。');document.getElementById('retry-quiz').hidden=correct;document.getElementById('show-hint').hidden=true;renderLessonNav()}
function addReview(r){state.reviews.unshift({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),date:new Date().toISOString(),seen:'',reason:'',takeaway:'',reviewed:false,...r})}

const controls={basics:[['price','每份单价',4,1,10,'元'],['count','数量',5,1,10,'份']],equation:[['start','原来的量',12,1,20,'个'],['add','增加的量',7,1,15,'个']],work:[['a','甲单独完成',6,2,20,'天'],['b','乙单独完成',8,2,20,'天']],motion:[['distance','两地距离',150,40,400,'公里'],['v1','甲的速度',60,10,100,'公里/时'],['v2','乙的速度',40,10,100,'公里/时']],profit:[['cost','成本',100,40,200,'元'],['price','标价',150,50,300,'元'],['discount','折扣',80,40,100,'%']],sets:[['total','总人数',40,20,80,'人'],['a','会 A 的人数',25,1,60,'人'],['b','会 B 的人数',20,1,60,'人'],['both','两种都会',10,0,40,'人']],mixture:[['liquid','原溶液',100,50,300,'克'],['percent','原浓度',20,5,60,'%'],['water','加入清水',100,0,300,'克']],counting:[['people','总人数',5,3,8,'人'],['choose','选出人数',2,2,3,'人']]};
function renderExplorer(type){let el=document.getElementById('explorer');el.innerHTML=`<h4>数字实验台</h4><p>数字改变后，模型会跟着变化。观察“什么不变、什么改变”。</p><div class="control-grid">${controls[type].map(([key,label,value,min,max,unit])=>`<div class="range-control"><label for="range-${key}">${label}<output id="output-${key}">${value}${unit}</output></label><input id="range-${key}" data-key="${key}" type="range" min="${min}" max="${max}" value="${value}" aria-label="${label}"></div>`).join('')}</div><div class="explorer-result" id="explorer-result"></div>`;el.querySelectorAll('input').forEach(input=>input.addEventListener('input',()=>{let c=controls[type].find(x=>x[0]===input.dataset.key);document.getElementById('output-'+input.dataset.key).textContent=input.value+c[5];updateExplorer(type)}));updateExplorer(type)}
function updateExplorer(type){let v=Object.fromEntries(controls[type].map(x=>[x[0],+document.getElementById('range-'+x[0]).value]));let html='';let bar=(label,pct,alt=false)=>`<div>${label}<span class="${alt?'alt':''}" style="width:${Math.max(4,Math.min(100,pct))}%"></span></div>`;
 if(type==='basics'){html=`<div class="diagram tokens">${Array.from({length:v.count},()=>`<span>¥${v.price}</span>`).join('')}</div>每一份 ${v.price} 元，共 ${v.count} 份。<br><strong>${v.price} × ${v.count} = ${v.price*v.count} 元</strong>`}
 if(type==='equation'){html=`<div class="diagram balance"><div><span>${v.start}</span><span>＋ ${v.add}</span></div><b>＝</b><div><span>${v.start+v.add}</span></div></div>等号两边是同一件事的两种说法。<br><strong>${v.start} + ${v.add} = ${v.start+v.add}</strong>`}
 if(type==='work'){let total=lcm(v.a,v.b),pa=total/v.a,pb=total/v.b,t=total/(pa+pb);html=`<div class="diagram work-diagram"><div class="work-lane">甲 <span style="--dur:${Math.max(1.2,v.a/4)}s"></span></div><div class="work-lane alt">乙 <span style="--dur:${Math.max(1.2,v.b/4)}s"></span></div></div>把任务分成 ${total} 份：甲每天做 ${pa} 份，乙每天做 ${pb} 份。<br><strong>合作 ${total} ÷ (${pa} + ${pb}) ≈ ${fmt(t)} 天</strong>`}
 if(type==='motion'){let t=v.distance/(v.v1+v.v2);html=`<div class="diagram road"><span class="traveler car-a" style="--travel:${Math.max(2,t*2)}s">甲 →</span><span class="road-line"></span><span class="traveler car-b" style="--travel:${Math.max(2,t*2)}s">← 乙</span></div>相向而行，每小时缩短 ${v.v1} + ${v.v2} = ${v.v1+v.v2} 公里。<br><strong>${v.distance} ÷ ${v.v1+v.v2} ≈ ${fmt(t)} 小时相遇</strong>`}
 if(type==='profit'){let sale=v.price*v.discount/100,profit=sale-v.cost,rate=profit/v.cost*100;html=`<div class="diagram visual-bars">${bar('成本',v.cost/Math.max(v.price,v.cost)*100)}${bar('标价',v.price/Math.max(v.price,v.cost)*100,true)}${bar('实售价',sale/Math.max(v.price,v.cost)*100)}</div>打 ${v.discount/10} 折后卖 ${fmt(sale)} 元，${profit>=0?'利润':'亏损'} ${fmt(Math.abs(profit))} 元。<br><strong>${profit>=0?'利润率':'亏损率'} = ${fmt(Math.abs(rate))}%（分母是成本）</strong>`}
 if(type==='sets'){let a=Math.min(v.a,v.total),b=Math.min(v.b,v.total);let lower=Math.max(0,a+b-v.total),upper=Math.min(a,b);let overlap=Math.min(upper,Math.max(lower,v.both));for(const [key,value] of [['a',a],['b',b],['both',overlap]]){document.getElementById('range-'+key).value=value;document.getElementById('output-'+key).textContent=value+'人'}let union=a+b-overlap,none=v.total-union;html=`<div class="diagram venn"><span class="venn-a">A<br>${a-overlap}</span><span class="venn-overlap">都<br>${overlap}</span><span class="venn-b">B<br>${b-overlap}</span></div>A + B 要减去重复计算的 ${overlap} 人。<br><strong>至少一种 ${union} 人；都不会 ${none} 人</strong>${v.both!==overlap?'<br><small>重叠人数已按条件自动调整。</small>':''}`}
 if(type==='mixture'){let salt=v.liquid*v.percent/100,total=v.liquid+v.water,rate=salt/total*100;html=`<div class="diagram beakers"><div class="beaker"><span class="water-wave" style="height:${Math.max(25,v.percent+20)}%"></span><b>${v.percent}%</b></div><span class="beaker-plus">+ ${v.water}g 水 →</span><div class="beaker"><span class="water-wave" style="height:${Math.max(25,rate+20)}%"></span><b>${fmt(rate)}%</b></div></div>盐一直是 ${fmt(salt)} 克，溶液从 ${v.liquid} 克变成 ${total} 克。<br><strong>新浓度 ${fmt(salt)} ÷ ${total} ≈ ${fmt(rate)}%</strong>`}
 if(type==='counting'){let n=v.people,k=Math.min(v.choose,n);let ordered=1;for(let i=0;i<k;i++)ordered*=n-i;let factorial=1;for(let i=2;i<=k;i++)factorial*=i;html=`<div class="diagram people-dots">${Array.from({length:n},(_,i)=>`<span>${i+1}</span>`).join('')}</div>分角色：${Array.from({length:k},(_,i)=>n-i).join(' × ')} = ${ordered} 种。<br><strong>不分角色：${ordered} ÷ ${factorial} = ${ordered/factorial} 种</strong>`}
 document.getElementById('explorer-result').innerHTML=html}
function gcd(a,b){while(b)[a,b]=[b,a%b];return a}function lcm(a,b){return a*b/gcd(a,b)}function fmt(n){return Number(n.toFixed(2))}

function setCube(x,y){cubeX=x;cubeY=y;document.getElementById('cube').style.transform=`rotateX(${x}deg) rotateY(${y}deg)`}
document.getElementById('rotate-left').addEventListener('click',()=>setCube(cubeX,cubeY-90));document.getElementById('rotate-right').addEventListener('click',()=>setCube(cubeX,cubeY+90));document.getElementById('rotate-up').addEventListener('click',()=>setCube(cubeX+90,cubeY));document.getElementById('rotate-down').addEventListener('click',()=>setCube(cubeX-90,cubeY));document.getElementById('reset-cube').addEventListener('click',()=>setCube(-25,-32));
const stage=document.getElementById('cube-stage');stage.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,cx:cubeX,cy:cubeY};stage.setPointerCapture(e.pointerId);document.getElementById('cube').classList.add('dragging')});stage.addEventListener('pointermove',e=>{if(drag)setCube(drag.cx+(drag.y-e.clientY)*.55,drag.cy+(e.clientX-drag.x)*.55)});function stopDrag(){drag=null;document.getElementById('cube').classList.remove('dragging')}stage.addEventListener('pointerup',stopDrag);stage.addEventListener('pointercancel',stopDrag);stage.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')setCube(cubeX,cubeY-15);if(e.key==='ArrowRight')setCube(cubeX,cubeY+15);if(e.key==='ArrowUp')setCube(cubeX+15,cubeY);if(e.key==='ArrowDown')setCube(cubeX-15,cubeY)}});
document.querySelectorAll('.cube-net button').forEach(b=>b.addEventListener('click',()=>selectFace(b.dataset.face)));
function selectFace(face){document.querySelectorAll('.cube-net button').forEach(b=>{b.classList.toggle('selected',b.dataset.face===face);b.classList.toggle('opposite',b.dataset.face===opposite[face])});document.querySelectorAll('.cube-face').forEach(x=>x.classList.toggle('highlight',x.dataset.face===face||x.dataset.face===opposite[face]));document.getElementById('face-note').innerHTML=`<b>${face}（${faceNames[face]}）</b> 的对面是 <b>${opposite[face]}（${faceNames[opposite[face]]}）</b>。两面没有公共边。`;let angles={A:[0,0],B:[0,-90],C:[-90,0],D:[0,90],E:[90,0],F:[0,180]};setCube(...angles[face])}
function renderSpatialQuiz(){let q=spatialQuestions[spatialIndex];spatialAnswered=false;document.getElementById('spatial-question').textContent=q.from+' 面的对面是哪一面？';document.getElementById('spatial-options').innerHTML=q.options.map(o=>`<button data-spatial-answer="${o}" aria-label="${o} 面">${o}</button>`).join('');document.getElementById('spatial-feedback').textContent='';document.getElementById('spatial-feedback').className='quiz-feedback';document.getElementById('next-spatial').hidden=true;document.querySelectorAll('[data-spatial-answer]').forEach(b=>b.addEventListener('click',()=>answerSpatial(b.dataset.spatialAnswer)))}
function answerSpatial(choice){if(spatialAnswered)return;spatialAnswered=true;let q=spatialQuestions[spatialIndex],correct=choice===q.answer;state.attempts.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),kind:'spatial',topic:'cube',correct,date:new Date().toISOString()});if(!correct)addReview({kind:'spatial',topic:'cube',title:'立方体相对面',question:q.from+' 面的对面是哪一面？',chosen:choice,answer:q.answer,explain:`${q.from} 与 ${q.answer} 相对。先在展开图中找相隔一个面的两个面，再旋转模型验证。`});save();document.querySelectorAll('[data-spatial-answer]').forEach(b=>{b.disabled=true;if(b.dataset.spatialAnswer===q.answer)b.classList.add('correct');if(b.dataset.spatialAnswer===choice&&!correct)b.classList.add('wrong')});let f=document.getElementById('spatial-feedback');f.className='quiz-feedback '+(correct?'good':'bad');f.textContent=(correct?'✓ 找对了！':'再看一眼展开图。')+` ${q.from} 与 ${q.answer} 相对。`+(correct?'':' 已加入错题复盘。');selectFace(q.from);document.getElementById('next-spatial').hidden=false}
document.getElementById('next-spatial').addEventListener('click',()=>{spatialIndex=(spatialIndex+1)%spatialQuestions.length;renderSpatialQuiz();document.getElementById('spatial-question').scrollIntoView({behavior:'smooth',block:'center'})});
document.querySelectorAll('[data-signal]').forEach(b=>b.addEventListener('click',()=>{document.getElementById('signal-detail').textContent=signalTips[b.dataset.signal];document.querySelectorAll('[data-signal]').forEach(x=>x.classList.toggle('selected',x===b))}));

function renderReviews(){refreshStats();let list=document.getElementById('review-list');if(!state.reviews.length){list.innerHTML='<div class="empty-state"><strong>这里还没有错题</strong><p>先做一道数量关系或空间图推练习。答错后会自动收进这里，方便你记录第一反应和下一次的做法。</p><button class="primary-btn" id="empty-start">开始练习 ↗</button></div>';document.getElementById('empty-start').addEventListener('click',()=>switchView('quantity'));return}list.innerHTML=state.reviews.map(r=>`<div class="review-card" data-review="${r.id}"><div class="review-card-top"><span class="tag ${r.reviewed?'':'error'}">${r.reviewed?'已复盘':'待复盘'}</span><b>${esc(r.title)}</b><small>${new Date(r.date).toLocaleDateString('zh-CN')}</small></div><p><b>题目：</b>${esc(r.question)}<br><b>你的答案：</b>${esc(r.chosen)}　<b>正确答案：</b>${esc(r.answer)}<br>${esc(r.explain)}</p><div class="review-form"><label>第一眼看到了什么？<input data-field="seen" value="${esc(r.seen)}" placeholder="如：看到两个速度就想相加"></label><label>卡点 / 错因<select data-field="reason"><option value="">请选择</option>${['概念没理解','题型方向判断错','条件漏看了','计算或验证失误','时间压力'].map(s=>`<option value="${s}" ${r.reason===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="wide">下次看到同类题，我先做什么？<input data-field="takeaway" value="${esc(r.takeaway)}" placeholder="写下能真正提醒自己的一个动作"></label></div><div class="review-card-actions"><button class="outline-btn" data-mark="${r.id}">${r.reviewed?'重新标为待复盘':'完成复盘 ✓'}</button><button class="text-btn" data-retry="${r.topic}">回到题目 →</button></div></div>`).join('');list.querySelectorAll('[data-review]').forEach(card=>{let id=card.dataset.review;card.querySelectorAll('[data-field]').forEach(input=>input.addEventListener('change',()=>{let r=state.reviews.find(x=>x.id===id);r[input.dataset.field]=input.value;save()}))});list.querySelectorAll('[data-mark]').forEach(b=>b.addEventListener('click',()=>{let r=state.reviews.find(x=>x.id===b.dataset.mark);r.reviewed=!r.reviewed;save();renderReviews()}));list.querySelectorAll('[data-retry]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.retry==='cube'){switchView('spatial');renderSpatialQuiz()}else{currentLesson=b.dataset.retry;state.lastLesson=currentLesson;save();switchView('quantity');renderLesson()}}))}
document.getElementById('export-records').addEventListener('click',()=>{let blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='解题有形-学习记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});

refreshStats();renderLesson();renderSpatialQuiz();switchView(location.hash.slice(1)||'home',false);
